import io

import pytest

from werkzeug.formparser import FormDataParser
from werkzeug.sansio.multipart import Data
from werkzeug.sansio.multipart import Epilogue
from werkzeug.sansio.multipart import Field
from werkzeug.sansio.multipart import File
from werkzeug.sansio.multipart import MultipartDecoder
from werkzeug.sansio.multipart import NeedData
from werkzeug.sansio.multipart import Preamble
from werkzeug.wrappers import Request


BOUNDARY = b"b.+(x)?$"
PAYLOAD = (
    b"\x00\r\n\r\n\xff"
    + b"".join(
        b"\r\n--" + BOUNDARY + suffix
        for suffix in (b"--X", b"--!", b"---", b"----", b" \tX", b"-- \tX")
    )
    + b"\r"
)


def message(newline=b"\r\n", closing_newline=True):
    result = b"preamble" + newline
    for filename, payload in ((None, b"first\x00\r"), ("a.bin", PAYLOAD), (None, b""), ("empty", b"")):
        result += b"--" + BOUNDARY + b" \t" + newline
        result += b'Content-Disposition: form-data; name="same"'
        if filename is not None:
            result += b'; filename="' + filename.encode() + b'"'
        result += newline + b"X-Test: value" + newline * 2 + payload + newline
    result += b"--" + BOUNDARY + b"-- \t"
    if closing_newline:
        result += newline + b"epilogue"
    return result


def decode(chunks):
    decoder = MultipartDecoder(BOUNDARY)
    result = []
    payload = bytearray()
    for chunk in [*chunks, None]:
        decoder.receive_data(chunk)
        while True:
            event = decoder.next_event()
            if isinstance(event, NeedData):
                break
            if isinstance(event, Data):
                payload.extend(event.data)
                if not event.more_data:
                    result.append(bytes(payload))
                    payload.clear()
            else:
                result.append(event)
            if isinstance(event, Epilogue):
                return result


@pytest.mark.parametrize("newline", [b"\r\n", b"\r", b"\n"])
@pytest.mark.parametrize("closing_newline", [True, False])
def test_every_split(newline, closing_newline):
    body = message(newline, closing_newline)
    expected = decode([body])
    assert [event for event in expected if isinstance(event, bytes)] == [
        b"first\x00\r", PAYLOAD, b"", b""
    ]
    assert [type(event) for event in expected] == [
        Preamble, Field, bytes, File, bytes, Field, bytes, File, bytes, Epilogue
    ]
    for split in range(len(body) + 1):
        assert decode([body[:split], body[split:]]) == expected, split
    for size in (1, 2, 3, 7, 31):
        assert decode([body[i:i + size] for i in range(0, len(body), size)]) == expected


class FragmentedStream(io.BytesIO):
    def read(self, size=-1):
        return super().read(min(size, 1))


@pytest.mark.parametrize("request", [False, True])
def test_form_parser_and_request(request):
    body = message()
    content_type = 'multipart/form-data; boundary="' + BOUNDARY.decode() + '"'
    if request:
        req = Request({
            "wsgi.input": FragmentedStream(body),
            "CONTENT_LENGTH": str(len(body)),
            "CONTENT_TYPE": content_type,
            "REQUEST_METHOD": "POST",
        })
        form, files = req.form, req.files
    else:
        _, form, files = FormDataParser(silent=False).parse(
            FragmentedStream(body), "multipart/form-data", len(body),
            {"boundary": BOUNDARY.decode()},
        )
    try:
        assert form.getlist("same") == ["first\x00\r", ""]
        uploaded = files.getlist("same")
        assert [(f.filename, f.read(), f.headers["X-Test"]) for f in uploaded] == [
            ("a.bin", PAYLOAD, "value"), ("empty", b"", "value")
        ]
    finally:
        for f in files.values():
            f.close()
        if request:
            req.close()


def test_request_final_cr_at_read_boundary():
    payload = b"\0" * 65535 + b"\r"
    with Request.from_values(
        data={"file": (io.BytesIO(payload), "sample.bin")}, method="POST"
    ) as request:
        assert request.files["file"].read() == payload


def test_streaming_and_ambiguous_close():
    decoder = MultipartDecoder(BOUNDARY)
    decoder.receive_data(
        b"--" + BOUNDARY + b'\r\nContent-Disposition: form-data; name="x"\r\n\r\n'
        + b"a" * 100000 + b"\r\n--" + BOUNDARY + b"-- \t"
    )
    assert isinstance(decoder.next_event(), Preamble)
    assert isinstance(decoder.next_event(), Field)
    assert decoder.next_event() == Data(b"a" * 100000, more_data=True)
    assert isinstance(decoder.next_event(), NeedData)
    decoder.receive_data(None)
    assert decoder.next_event() == Data(b"", more_data=False)
    assert decoder.next_event() == Epilogue(b"")


@pytest.mark.parametrize("suffix", [b"", b"--X", b"--!", b"---", b"----", b"-- \tX"])
def test_missing_valid_close(suffix):
