        b"--" + BOUNDARY + b'\r\nContent-Disposition: form-data; name="x"\r\n\r\n'
        + b"payload\r\n--" + BOUNDARY + suffix
    )
    with pytest.raises(ValueError):
        decode([body[i:i + 1] for i in range(len(body))])
